void real(const fs::path& input,const fs::path& output){
    fs::create_directory(output);const auto imported=import_expression_matrix((input/"matrix.mtx").u8string(),(input/"features.tsv").u8string(),(input/"observations.tsv").u8string(),(output/"source.qmx").u8string());const auto matrix=open_expression_matrix(imported.path,imported.file_sha256);
    Project project;const auto image=project.add_document(std::make_shared<Document>(dense_image_server(Image::demo())));keep_expression_matrix(project,image,matrix,true);project.save_new((output/"input.qpx").u8string());ExpressionAggregationWorkflowOptions a;a.image=image;a.matrix_id=matrix->metadata().source_sha256;a.spec_path=(input/"cohorts.json").u8string();const auto bulk=run_expression_aggregation((output/"input.qpx").u8string(),(output/"pseudobulk.qpx").u8string(),a);
    ExpressionDifferentialWorkflowOptions o;o.image=image;o.aggregation_id=bulk->id();o.statistics.group_a="F";o.statistics.group_b="M";const auto r=run_expression_differential((output/"pseudobulk.qpx").u8string(),(output/"differential.qpx").u8string(),o);check(r->n_a()==2 && r->n_b()==4 && r->replicates().size()==6,"Real data lacks the admitted2 female/4 male independent mice");
    o.aggregation_id.clear();o.statistics.group_a.clear();o.statistics.group_b.clear();o.record_id=r->id();o.statistics.work_bytes=64u*1024*1024;const auto replay=open_project_expression_differential((output/"differential.qpx").u8string(),o);check(replay->recipe()==r->recipe(),"Real exact saved replay differs at64MiB");save_expression_differential_csv(*replay,(output/"genes.csv").u8string());save_expression_differential_replicates_csv(*replay,(output/"replicates.csv").u8string());save_expression_aggregation_csv(*bulk,(output/"pseudobulk.csv").u8string());
    const J report={{"image",image},{"source",matrix->metadata().source_sha256},{"features",r->genes().size()},{"observations",matrix->metadata().observations},{"pseudobulk",bulk->id()},{"record",r->id()},{"result_sha256",r->sha256()},{"testable_features",r->correction_features()},{"n_a",r->n_a()},{"n_b",r->n_b()},{"peak_work_bytes",r->peak_work_bytes()},{"scope","Tabula Muris kidney sex comparison; independent numerical/association check; no biological discovery claim"}};write(output/"real.json",report.dump(2)+"\n");std::cout<<report.dump()<<'\n';
}
int main(int argc,char** argv){try{if(!has_expression_matrix_storage()){std::cout<<"Native matrix storage disabled\n";return 0;}if(argc==3){real(fs::u8path(argv[1]),fs::u8path(argv[2]));return 0;}if(argc!=1)throw std::invalid_argument("Expected no arguments or REAL_INPUT NEW_EVIDENCE_DIRECTORY");const auto root=fs::current_path()/("differential-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));fs::create_directory(root);exercise(root);std::cout<<"Native A04: replicate consolidation, independent/analytical Welch/BH, degeneracy, raw preservation, refusal/bounds, saved replay/relocation and native CLI/CSV pass\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
